import {roundedBox} from './rounded-geometry.js';
import * as T from './vendor/three.module.js';
const loader=new T.TextureLoader();T.DefaultLoadingManager.onProgress=(_url,loaded,total)=>{const label=document.querySelector('#save-status');if(label&&document.querySelector('#start')?.disabled)label.textContent='Загрузка текстур: '+loaded+' / '+total};T.DefaultLoadingManager.onError=()=>{const label=document.querySelector('#save-status');if(label)label.textContent='Не удалось загрузить текстуру. Проверьте соединение и обновите страницу.'};
const names=['стражник_лицо', 'стражник_кольчуга', 'стражник_рукава', 'стражник_кожа', 'кузнец_лицо', 'кузнец_фартук', 'кузнец_рубаха', 'кузнец_штаны', 'могильщик_лицо', 'могильщик_жилет', 'могильщик_плащ', 'могильщик_штаны', 'женщина_лицо', 'женщина_платье', 'женщина_фартук', 'женщина_платок', 'человек_кожа', 'волосы', 'волк_шерсть', 'волк_морда', 'волк_лапы', 'заяц_шерсть', 'заяц_морда', 'заяц_уши', 'ворон_перья', 'ворон_крыло', 'ворон_голова'];
const textures=Object.fromEntries(await Promise.all(names.map(async n=>{const t=await loader.loadAsync('./assets/'+n+'.webp');t.colorSpace=T.SRGBColorSpace;return [n,t]})));
const witchAtlas=await loader.loadAsync('./assets/ведьма_атлас.webp');witchAtlas.colorSpace=T.SRGBColorSpace;
for(const [name,x,y] of [['ведьма_лицо',0,.5],['ведьма_роба',.5,.5],['ведьма_кожа',0,0],['ведьма_шляпа',.5,0]]){const t=witchAtlas.clone();t.repeat.set(.5,.5);t.offset.set(x,y);textures[name]=t}
export function witchMaterial(name){return material('ведьма_'+name)}
const sets={hunter:['могильщик_жилет','могильщик_лицо','стражник_кожа','кузнец_рубаха'],witch:['ведьма_роба','ведьма_лицо','ведьма_кожа','ведьма_роба'],guard:['стражник_кольчуга','стражник_лицо','стражник_кожа','стражник_рукава'],smith:['кузнец_фартук','кузнец_лицо','кузнец_штаны','кузнец_рубаха'],digger:['могильщик_жилет','могильщик_лицо','могильщик_штаны','могильщик_плащ'],woman:['женщина_платье','женщина_лицо','женщина_платье','женщина_платье'],wolf:['волк_шерсть','волк_морда','волк_лапы','волк_шерсть'],hare:['заяц_шерсть','заяц_морда','заяц_шерсть','заяц_шерсть'],raven:['ворон_перья','ворон_голова','ворон_перья','ворон_крыло']};
function material(name){return new T.MeshStandardMaterial({map:textures[name],roughness:.9,flatShading:false})}

export function modelActor(scene,maps,x,z,height,animal=false,role="guard"){
const g=new T.Group();g.position.set(x,0,z);scene.add(g);const limbs=[];
const selected=sets[animal===true?'wolf':animal||role];const body=material(selected[0]),face=material(selected[1]),legs=material(selected[2]),sleeves=material(selected[3]),skin=material(animal?selected[0]:'человек_кожа'),hair=material('волосы');
const headMaterials=[skin,skin,animal?skin:hair,skin,face,animal?skin:hair];
function part(parent,w,h,d,px,py,pz,material){const m=new T.Mesh(roundedBox(w,h,d),material);m.position.set(px,py,pz);parent.add(m);return m}
function limb(px,py,pz,w,h,d,cover=legs){const joint=new T.Group();joint.position.set(px,py,pz);g.add(joint);part(joint,w,h,d,0,-h/2,0,cover);limbs.push(joint)}
if(!animal){part(g,.46,.64,.28,0,1.05,0,body);part(g,.31,.35,.30,0,1.57,.015,headMaterials);part(g,.13,.14,.13,0,1.36,0,skin);for(const s of [-1,1]){limb(s*.14,.76,0,.19,.72,.22);limb(s*.34,1.34,0,.15,.62,.18,sleeves)}
if(role==='hunter'){body.color.set(0x697454);sleeves.color.set(0x718069);legs.color.set(0x685340);face.color.set(0xc9bcb0);part(g,.56,.14,.36,0,1.83,0,legs);const quiver=part(g,.20,.59,.19,.23,1.12,-.26,legs);quiver.rotation.z=-.2;for(let i=0;i<4;i++)part(g,.025,.36,.025,.16+i*.045,1.53,-.26,body);const bow=new T.Group();bow.position.set(0,-.60,.02);limbs[1].add(bow);const curve=new T.QuadraticBezierCurve3(new T.Vector3(0,-.45,0),new T.Vector3(0,0,.3),new T.Vector3(0,.45,0));bow.add(new T.Mesh(new T.TubeGeometry(curve,16,.025,6,false),new T.MeshStandardMaterial({color:0x8b643b})));const string=new T.Line(new T.BufferGeometry().setFromPoints([new T.Vector3(0,-.45,0),new T.Vector3(0,0,0),new T.Vector3(0,.45,0)]),new T.LineBasicMaterial({color:0xd1c7aa}));bow.add(string);g.userData.bow=bow;g.userData.string=string;g.userData.arms=[limbs[1],limbs[3]];}if(role==='witch'){part(g,.48,.72,.34,0,.58,0,body)}if(role==='woman'){part(g,.45,.58,.31,0,.68,.02,body);part(g,.34,.52,.02,0,.76,.19,material('женщина_фартук'));part(g,.34,.12,.32,0,1.77,.01,material('женщина_платок'));}if(role==='digger')part(g,.54,.75,.06,0,1.04,-.18,material('могильщик_плащ'));
}else if(animal==='hare'){
const oval=(w,h,d,x,y,z,mat)=>{const m=new T.Mesh(new T.SphereGeometry(1,12,10),mat);m.scale.set(w/2,h/2,d/2);m.position.set(x,y,z);g.add(m);return m};
oval(.62,.65,.69,0,.49,-.12,body);oval(.37,.36,.36,0,.72,.27,face);oval(.23,.20,.16,0,.64,.45,skin);oval(.22,.22,.22,0,.47,-.51,skin);
for(const side of [-1,1]){const ear=oval(.12,.67,.075,side*.10,1.13,.23,material('заяц_уши'));ear.rotation.z=side*.14;oval(.27,.38,.34,side*.22,.30,-.20,body);limb(side*.14,.35,.25,.09,.24,.12);oval(.18,.10,.28,side*.23,.10,-.08,legs);const eye=oval(.045,.065,.045,side*.145,.77,.385,new T.MeshStandardMaterial({color:0x171215,roughness:.2}));}oval(.07,.055,.04,0,.68,.535,new T.MeshStandardMaterial({color:0xbe8c8c}));
}else if(animal==='raven'){part(g,.34,.48,.48,0,.52,0,body);part(g,.24,.25,.28,0,.88,.16,[face,face,body,body,body,body]);const beak=new T.Mesh(new T.ConeGeometry(.10,.30,4),new T.MeshStandardMaterial({color:0x252a30}));beak.rotation.x=Math.PI/2;beak.position.set(0,.88,.42);g.add(beak);for(const side of [-1,1]){limb(side*.10,.33,0,.05,.30,.06);part(g,.08,.35,.45,side*.20,.56,0,sleeves);}}else{part(g,.42,.43,.94,0,.67,0,body);part(g,.32,.35,.38,0,.88,.52,headMaterials);part(g,.22,.17,.29,0,.81,.79,body);for(const side of [-1,1]){const ear=new T.Mesh(new T.ConeGeometry(.10,animal==="hare"?.65:.24,4),animal==="hare"?material("заяц_уши"):skin);ear.position.set(side*.12,1.15,.53);g.add(ear);for(const z of [-.32,.32])limb(side*.18,.58,z,.12,.53,.14)}const tail=part(g,.12,.12,.53,0,.65,-.67,body);tail.rotation.x=-.45;}
if(!animal)g.userData.arms=[limbs[1],limbs[3]];const rig=new T.Group();for(const child of [...g.children])rig.add(child);g.add(rig);let attackLeft=0,attackDuration=.7,attackKind='';
const castOrb=new T.Mesh(new T.SphereGeometry(.15,10,8),new T.MeshBasicMaterial({color:0x93ff74,transparent:true,opacity:.85}));castOrb.position.set(.35,1.4,.35);castOrb.visible=false;rig.add(castOrb);
const scale=height/(animal?1.25:1.78);g.scale.setScalar(scale);let last=new T.Vector3(x,0,z),phase=0;
return {g,x,z,heading:0,height,cueAttack(kind,duration=.7){attackKind=kind;attackDuration=duration;attackLeft=duration},animate(dt){if(this.stun>0)return;attackLeft=Math.max(0,attackLeft-dt*(this.slow>0?.5:1));rig.position.z=0;rig.rotation.x=0;castOrb.visible=false;for(const l of limbs)l.rotation.z=0;if(attackLeft>0){const t=1-attackLeft/attackDuration,pulse=Math.sin(t*Math.PI);if(attackKind==='bite'){rig.position.z=.32*pulse;rig.rotation.x=-.18*pulse;for(const l of limbs)l.rotation.x=-.65*pulse}else{const arms=g.userData.arms||[limbs[1],limbs[3]];if(attackKind==='bow'){const draw=t<.26?t/.26:Math.max(0,1-(t-.26)/.12);if(arms[0])arms[0].rotation.x=-1.45;if(arms[1]){arms[1].rotation.x=-1.3+draw*.35;arms[1].rotation.z=-draw*.5}const attr=g.userData.string?.geometry.attributes.position;if(attr){attr.setXYZ(1,0,0,-.25*draw);attr.needsUpdate=true}}else{arms.forEach((a,i)=>{if(a){a.rotation.x=-1.6*pulse;a.rotation.z=(i?1:-1)*pulse*.4}});castOrb.visible=true;castOrb.scale.setScalar(.7+pulse*1.3);rig.rotation.x=-.10*pulse}}}},update(){const speed=g.position.distanceTo(last);last.copy(g.position);if(speed>.0001)phase+=Math.min(.5,speed*8);limbs.forEach((l,i)=>l.rotation.x=speed>.0001?Math.sin(phase+(animal?(i%2):[0,1,1,0][i])*Math.PI)*(!animal&&i%2===1?.35:.55):0);g.rotation.y=this.heading;}};
}

